export function formatPrice(p) {
  if (p === null || p === undefined || p === "") return "-";

  const text = String(p);
  const match = text.match(/^([+-]?)(\d+)(?:\.(\d*))?(?:[eE]([+-]?\d+))?$/);

  if (!match) return "-";

  const [, sign, integerPart, fractionPart = "", exponentPart = "0"] = match;
  const digits = integerPart + fractionPart;
  let scale = fractionPart.length - Number(exponentPart);
  let numerator = BigInt(digits);

  if (sign === "-" && numerator !== 0n) return "var";

  if (scale < 0) {
    numerator *= 10n ** BigInt(-scale);
    scale = 0;
  }

  // One million tokens, expressed in cents: price * 1_000_000 * 100.
  const targetScale = 8;
  let cents;

  if (scale <= targetScale) {
    cents = numerator * 10n ** BigInt(targetScale - scale);
  } else {
    const divisor = 10n ** BigInt(scale - targetScale);
    const quotient = numerator / divisor;
    const remainder = numerator % divisor;
    cents = remainder * 2n >= divisor ? quotient + 1n : quotient;
  }

  const whole = cents / 100n;
  const fraction = (cents % 100n).toString().padStart(2, "0");

  return `$${whole}.${fraction}`;
}
