  const input = String(p).trim();
  const match = input.match(/^([+-]?)(\d*)(?:\.(\d*))?(?:[eE]([+-]?\d+))?$/);

  if (!match || (match[2] === "" && (match[3] ?? "") === "")) return "-";

  const sign = match[1] === "-" ? -1n : 1n;
  const digits = `${match[2]}${match[3] ?? ""}`;

  if (digits === "") return "-";

  let coefficient = BigInt(digits);
  const exponent = BigInt(match[4] ?? "0");
  let scale = BigInt((match[3] ?? "").length) - exponent;

  if (coefficient === 0n) return "$0.00";
  if (sign < 0n) return "var";

  if (scale < 0n) {
    coefficient *= 10n ** -scale;
    scale = 0n;
  }

  const denominator = 10n ** scale;
  const numerator = coefficient * 100000000n;
  const quotient = numerator / denominator;
  const remainder = numerator % denominator;
  const cents = quotient + (remainder * 2n >= denominator ? 1n : 0n);

  const dollars = cents / 100n;
  const fractional = cents % 100n;

  return `$${dollars}.${fractional.toString().padStart(2, "0")}`;
}
